CREATE TABLE article_reviews (id CHAR(36) PRIMARY KEY, article_id CHAR(36) NOT NULL, model VARCHAR(100) NULL, category VARCHAR(500) NULL, check_type VARCHAR(50) NULL, reviewed_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(article_id) REFERENCES articles(id) ON DELETE CASCADE, INDEX idx_article_reviews_article_date(article_id, reviewed_at));
CREATE TABLE article_review_findings (id CHAR(36) PRIMARY KEY, review_id CHAR(36) NOT NULL, field_name VARCHAR(20) NOT NULL DEFAULT 'content', finding_type VARCHAR(30) NOT NULL, severity ENUM('low','medium','high') NOT NULL DEFAULT 'low', quote VARCHAR(500) NOT NULL, sentence_quote TEXT NULL, neutral_rewrite TEXT NULL, explanation TEXT NOT NULL, suggestion TEXT NOT NULL, status ENUM('pending','dismissed','applied') NOT NULL DEFAULT 'pending', action VARCHAR(30) NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(review_id) REFERENCES article_reviews(id) ON DELETE CASCADE, INDEX idx_review_findings_review(review_id, created_at));
CREATE TABLE topic_history (id CHAR(36) PRIMARY KEY, topic VARCHAR(500) NOT NULL, normalized VARCHAR(500) NOT NULL, source ENUM('suggested','generated') NOT NULL DEFAULT 'suggested', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_topic_normalized(normalized(191)), INDEX idx_topic_created(created_at));
CREATE TABLE language_references (id CHAR(36) PRIMARY KEY, language_id VARCHAR(10) NOT NULL, reference_type ENUM('spelling','grammar') NOT NULL, source_name VARCHAR(255) NOT NULL, license VARCHAR(255) NOT NULL, version VARCHAR(100) NOT NULL, source_reference VARCHAR(500) NOT NULL, checksum VARCHAR(128) NULL, review_state ENUM('planned','reviewed','approved') NOT NULL DEFAULT 'planned', validation_state ENUM('not-validated','verified') NOT NULL DEFAULT 'not-validated', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_language_references_language(language_id, reference_type), INDEX idx_language_references_review(review_state, validation_state));
CREATE TABLE system_activity_logs (id CHAR(36) PRIMARY KEY, category VARCHAR(40) NOT NULL, event_type VARCHAR(100) NOT NULL, severity ENUM('info','warning','error','critical') NOT NULL DEFAULT 'info', outcome ENUM('success','rejected','failure','observed') NOT NULL DEFAULT 'success', actor_type ENUM('administrator','system','anonymous') NOT NULL DEFAULT 'system', actor VARCHAR(255) NULL, `source` VARCHAR(100) NOT NULL, `action` VARCHAR(255) NOT NULL, target_type VARCHAR(60) NULL, target_id VARCHAR(255) NULL, target_label VARCHAR(500) NULL, method VARCHAR(10) NULL, path VARCHAR(500) NULL, status_code SMALLINT UNSIGNED NULL, ip_address VARCHAR(45) NULL, user_agent VARCHAR(500) NULL, details JSON NULL, created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), INDEX idx_activity_created(created_at), INDEX idx_activity_category_created(category, created_at), INDEX idx_activity_severity_created(severity, created_at), INDEX idx_activity_actor_created(actor, created_at), INDEX idx_activity_event_created(event_type, created_at));
